<body>
    <div id="root"></div>

    <script type="text/babel">
        const { useState, useEffect, useRef } = React;

        function Modal({ isOpen, onClose, onConfirm }) {
            const modalRef = useRef(null);
            const firstElementRef = useRef(null);
            const lastElementRef = useRef(null);

            useEffect(() => {
                if (isOpen) {
                    // Prevent scrolling on body when modal is open
                    document.body.style.overflow = 'hidden';

                    const handleKeyDown = (e) => {
                        if (e.key === 'Escape') onClose();
                        if (e.key === 'Tab') {
                            if (e.shiftKey) { // Shift + Tab
                                if (document.activeElement === firstElementRef.current) {
                                    e.preventDefault();
                                    lastElementRef.current.focus();
                                }
                            } else { // Tab
                                if (document.activeElement === lastElementRef.current) {
                                    e.preventDefault();
                                    firstElementRef.current.focus();
                                }
                            }
                        }
                    };

                    document.addEventListener('keydown', handleKeyDown);

                    // Focus the "Cancel" button by default
                    if (firstElementRef.current) {
                        firstElementRef.current.focus();
                    }

                    return () => {
                        document.removeEventListener('keydown', handleKeyDown);
                        document.body.style.overflow = 'unset';
                    };
                }
            }, [isOpen, onClose]);

            if (!isOpen) return null;

            return ReactDOM.createPortal(
                <div className="modal-overlay" onClick={onClose} aria-hidden="true">
                    <div 
                        className="modal-content" 
                        role="dialog" 
                        aria-modal="true" 
                        aria-labelledby="modal-title" 
                        aria-describedby="modal-desc"
                        onClick={e => e.stopPropagation()}
                        ref={modalRef}
                    >
                        <div className="modal-header">
                            <div className="modal-icon" aria-hidden="true">
                                <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M3 6h18"></path><path d="M19 6v14c0 1-1 2-2 2H7c-1 0-2-1-2-2V6"></path><path d="M8 6V4c0-1 1-2 2-2h4c1 0 2 1 2 2v2"></path><line x1="10" y1="11" x2="10" y2="17"></line><line x1="14" y1="11" x2="14" y2="17"></line></svg>
                            </div>
                            <h2 id="modal-title" className="modal-title">Delete image</h2>
                        </div>
                        <p id="modal-desc" className="modal-description">
                            Are you sure you want to delete this image? This action will permanently remove it from your library.
                        </p>
                        <div className="modal-actions">
                            <button 
                                ref={firstElementRef}
                                className="btn btn-secondary" 
                                onClick={onClose}
                            >
                                Cancel
                            </button>
                            <button 
                                ref={lastElementRef}
                                className="btn btn-danger" 
                                onClick={onConfirm}
                            >
                                Delete
                            </button>
                        </div>
                    </div>
                </div>,
                document.body
            );
        }

        function App() {
            const [isModalOpen, setIsModalOpen] = useState(false);
            const triggerRef = useRef(null);

            const handleOpenModal = () => setIsModalOpen(true);
            const handleCloseModal = () => {
                setIsModalOpen(false);
                // Return focus to the trigger element
                if (triggerRef.current) {
                    triggerRef.current.focus();
                }
            };

            const handleConfirmDelete = () => {
                // In a real app, this would call an API
                console.log("Image deleted successfully");
                handleCloseModal();
            };

            return (
                <main className="container">
                    <h1>Image Preview</h1>
                    <div className="image-container">
                        <img 
                            src="https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?auto=format&fit=crop&q=80&w=800" 
                            alt="Abstract dark mountain landscape" 
                            className="image-preview" 
                        />
                    </div>
                    <div className="controls">
                        <button 
                            ref={triggerRef}
                            className="trigger" 
                            onClick={handleOpenModal}
                            aria-haspopup="dialog"
                            aria-expanded={isModalOpen}
                        >
                            <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d="M3 6h18"></path><path d="M19 6v14c0 1-1 2-2 2H7c-1 0-2-1-2-2V6"></path><path d="M8 6V4c0-1 1-2 2-2h4c1 0 2 1 2 2v2"></path></svg>
                            Delete from Library
                        </button>
                    </div>

                    <Modal 
                        isOpen={isModalOpen} 
                        onClose={handleCloseModal} 
                        onConfirm={handleConfirmDelete} 
                    />
                </main>
            );
        }

        const root = ReactDOM.createRoot(document.getElementById('root'));
        root.render(<App />);
    </script>

</body>
</html>
